changeSet.sql:
ALTER TABLE section_chats ALTER COLUMN section_id DROP NOT NULL;
ALTER TABLE section_chats ADD COLUMN activite_id bigint REFERENCES activites(id) ON DELETE CASCADE;
ALTER TABLE section_chats ADD COLUMN cible varchar(20) NOT NULL DEFAULT 'SECTION';
ALTER TABLE section_chats ADD CONSTRAINT chk_section_chat_target CHECK (
  (cible = 'SECTION' AND section_id IS NOT NULL AND activite_id IS NULL)
  OR (cible = 'ACTIVITE' AND section_id IS NULL AND activite_id IS NOT NULL)
  OR (cible = 'ASSOCIATION' AND section_id IS NULL AND activite_id IS NULL)
);
